mapper.select:
SELECT *
FROM (
    SELECT ROWNUM AS rn, inner_query.*
    FROM (
        SELECT *
        FROM FAQ_TB
        WHERE 1=1

            AND (question LIKE '%' || #{query} || '%' OR answer LIKE '%' || #{query} || '%')

        ORDER BY id -- 정렬 기준이 되는 컬럼을 지정하세요
    ) inner_query
    WHERE ROWNUM <= #{offset} + #{size}
)
WHERE rn > #{offset}
